/* ============================== AUTH ============================== */
const AUTHORIZED_USERS = [
  { full: "Kuldeep Rawat", role: "admin" },
  { full: "Shivas Behl", role: "shivas" },
  { full: "Pratham Mittal", role: "pratham" },
];

function matchUser(input) {
  const q = (input || "").trim().toLowerCase();
  if (!q) return null;
  for (const u of AUTHORIZED_USERS) {
    const full = u.full.toLowerCase();
    const first = full.split(" ")[0];
    if (q === first || q === full || full.startsWith(q)) return u;
  }
  return null;
}

const ROLE_LABELS = { admin: "Admin", shivas: "Evaluator — Stage 1", pratham: "Evaluator — Stage 2" };
const ROLE_NAV = {
  admin: ["dashboard", "queue", "all", "quick", "analysis", "downloads", "settings"],
  shivas: ["queue", "all", "quick", "analysis"],
  pratham: ["queue", "all", "quick", "analysis"],
};

function AccessScreen({ onAuthenticated }) {
  const [name, setName] = useState("");
  const [denied, setDenied] = useState(false);
  const [checking, setChecking] = useState(false);

  const submit = () => {
    const match = matchUser(name);
    if (match) {
      setDenied(false);
      setChecking(true);
      setTimeout(() => onAuthenticated(match), 400);
    } else {
      setDenied(true);
    }
  };

  return (
    <div style={{
      minHeight: "100vh", background: "#0B0B0C", display: "flex", alignItems: "center", justifyContent: "center",
      padding: 20, position: "relative", overflow: "hidden",
    }}>
      <GlobalStyle />
      <svg width="700" height="700" viewBox="0 0 700 700" style={{ position: "absolute", top: -120, right: -160, opacity: 0.5 }}>
        <path d="M40 400 L200 250 L150 340 L340 200 L250 380 L460 240 L200 500 L280 380 Z" fill="none" stroke="url(#g1)" strokeWidth="6" strokeLinecap="round" />
        <defs>
          <linearGradient id="g1" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="#39B6D8" /><stop offset="50%" stopColor="#F7D344" /><stop offset="100%" stopColor="#E38330" />
          </linearGradient>
        </defs>
      </svg>
      <div style={{ width: "100%", maxWidth: 420, position: "relative", zIndex: 1 }}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 34 }}>
          <MULogo variant="white" height={30} />
        </div>
        <div style={{
          background: "#141414", border: "1px solid #262626", borderRadius: 20, padding: "34px 30px",
          boxShadow: "0 30px 80px rgba(0,0,0,0.5)",
        }}>
          <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: ".12em", textTransform: "uppercase", color: "#39B6D8", marginBottom: 8, textAlign: "center" }}>
            C8 Profile Evaluation Access
          </div>
          <h1 style={{ color: "#fff", fontSize: 22, fontWeight: 800, textAlign: "center", margin: "0 0 6px" }}>Who are you?</h1>
          <p style={{ color: "#A3A3A3", fontSize: 13, textAlign: "center", margin: "0 0 26px", lineHeight: 1.5 }}>
            This admissions evaluation dashboard is restricted to authorised evaluators.
          </p>
          <input
            autoFocus
            className="mu-input"
            placeholder="Enter your name"
            value={name}
            onChange={(e) => { setName(e.target.value); setDenied(false); }}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            style={{ background: "#0B0B0C", borderColor: "#333", color: "#fff", padding: "13px 14px", fontSize: 15, textAlign: "center" }}
          />
          <button className="mu-btn mu-btn-primary" style={{ width: "100%", marginTop: 14, padding: "12px 16px", fontSize: 14 }} onClick={submit} disabled={checking}>
            {checking ? "Verifying…" : "Enter"}
          </button>
          {denied && (
            <div style={{ marginTop: 16, padding: "12px 14px", borderRadius: 10, background: "rgba(192,57,43,0.12)", border: "1px solid rgba(192,57,43,0.3)", color: "#E88", fontSize: 12.5, textAlign: "center", lineHeight: 1.5 }}>
              Access restricted. This dashboard is available only to authorised evaluators.
            </div>
          )}
        </div>
        <div style={{ textAlign: "center", marginTop: 20, color: "#525252", fontSize: 11.5 }}>
          Masters' Union · Internal Admissions Platform
        </div>
      </div>
    </div>
  );
}

