function TourOverlay({ role, onFinish, isModalOpen }) {
  const steps = TOUR_STEPS[role] || [];
  const [i, setI] = useState(0);
  const [rect, setRect] = useState(null);
  const step = steps[i];

  useEffect(() => {
    if (!step) return;
    if (step.requiresModal && !isModalOpen) return; // wait until modal is actually open
    const update = () => {
      const el = document.querySelector(step.target);
      if (el) setRect(el.getBoundingClientRect());
      else setRect(null);
    };
    update();
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, true);
    const t = setInterval(update, 250);
    return () => { window.removeEventListener("resize", update); window.removeEventListener("scroll", update, true); clearInterval(t); };
  }, [i, step, isModalOpen]);

  if (!step) return null;
  if (step.requiresModal && !isModalOpen) {
    // gently instruct user to open feedback modal first
    return (
      <div style={{ position: "fixed", inset: 0, zIndex: 500, background: "rgba(11,11,12,0.55)", display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
        <TourCard title="Open the feedback panel" body='Click "Give Feedback" to continue the tour.' i={i} total={steps.length}
          onBack={() => setI(Math.max(0, i - 1))} onNext={null} onSkip={onFinish} onFinish={null} />
      </div>
    );
  }

  const tooltipPos = rect ? {
    top: Math.min(rect.bottom + 14, window.innerHeight - 200),
    left: Math.min(Math.max(rect.left, 16), window.innerWidth - 320),
  } : { top: "50%", left: "50%", transform: "translate(-50%,-50%)" };

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 500, pointerEvents: "none" }}>
      {rect && (
        <div style={{
          position: "fixed", top: rect.top - 6, left: rect.left - 6, width: rect.width + 12, height: rect.height + 12,
          borderRadius: 10, boxShadow: "0 0 0 4000px rgba(11,11,12,0.55), 0 0 0 3px #F7D344", transition: "all .2s ease", pointerEvents: "none",
        }} />
      )}
      {!rect && <div style={{ position: "fixed", inset: 0, background: "rgba(11,11,12,0.55)" }} />}
      <div style={{ position: "fixed", ...tooltipPos, pointerEvents: "auto" }}>
        <TourCard title={step.title} body={step.body} i={i} total={steps.length}
          onBack={i > 0 ? () => setI(i - 1) : null}
          onNext={i < steps.length - 1 ? () => setI(i + 1) : null}
          onSkip={onFinish}
          onFinish={i === steps.length - 1 ? onFinish : null} />
      </div>
    </div>
  );
}

function TourCard({ title, body, i, total, onBack, onNext, onSkip, onFinish }) {
  return (
    <div style={{ width: 300, background: "#fff", borderRadius: 14, boxShadow: "0 16px 40px rgba(0,0,0,0.3)", padding: 16 }}>
      <div style={{ fontSize: 10.5, fontWeight: 700, color: "#A3A3A3", letterSpacing: ".06em", textTransform: "uppercase", marginBottom: 6 }}>Step {i + 1} of {total}</div>
      <div style={{ fontWeight: 800, fontSize: 15, marginBottom: 5 }}>{title}</div>
      <div style={{ fontSize: 13, color: "#525252", lineHeight: 1.5, marginBottom: 14 }}>{body}</div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <button className="mu-btn mu-btn-ghost" style={{ padding: "6px 8px", fontSize: 12 }} onClick={onSkip}>Skip Tour</button>
        <div style={{ display: "flex", gap: 6 }}>
          {onBack && <button className="mu-btn mu-btn-secondary" style={{ padding: "6px 10px", fontSize: 12 }} onClick={onBack}>Back</button>}
          {onNext && <button className="mu-btn mu-btn-primary" style={{ padding: "6px 12px", fontSize: 12 }} onClick={onNext}>Next</button>}
          {onFinish && <button className="mu-btn mu-btn-primary" style={{ padding: "6px 12px", fontSize: 12 }} onClick={onFinish}>Finish</button>}
        </div>
      </div>
    </div>
  );
}

/* ============================== PLACEHOLDER FOR DATA ============================== */
const CANDIDATES_B64 = "";

function decodeCandidates(b64) {
  try {
    const json = decodeURIComponent(escape(atob(b64)));
    return JSON.parse(json);
  } catch (e) {
    console.error("decode error", e);
    return [];
  }
}

/* ============================== HELPERS ============================== */
const val = (row, key) => {
  const v = row && row[key];
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  return s === "" ? null : s;
};
const disp = (v) => (v === null || v === undefined || v === "" ? "NA" : v);
const isNA = (v) => v === null || v === undefined || v === "";

function fmtMoney(v, currency) {
  if (isNA(v)) return "NA";
  const n = Number(v);
  if (isNaN(n)) return v;
  const cur = currency || "INR";
  if (n >= 100000 && cur === "INR") return `₹${(n / 100000).toFixed(2)}L`;
  return `${cur} ${n.toLocaleString()}`;
}

function fmtMonths(v) {
  if (isNA(v)) return "NA";
  const n = Number(v);
  if (isNaN(n)) return v;
  const y = Math.floor(n / 12);
  const m = Math.round(n % 12);
  if (y === 0) return `${m} mo`;
  if (m === 0) return `${y} yr`;
  return `${y} yr ${m} mo`;
}

function openLink(url) {
  if (!url) return;
  window.open(url, "_blank", "noopener,noreferrer");
}

