/* ---- profile completeness ---- */
function completeness(c) {
  const checks = [
    c.email, c.phone, c.dob, c.gender, c.linkedin, c.cv, c.course,
    c.class10.score, c.class12.score, c.grad.degree,
    c.currentDesignation || c.corporateExp.length, c.hasWorkExp,
  ];
  const filled = checks.filter((v) => !isNA(v) && v !== false).length;
  return Math.round((filled / checks.length) * 100);
}

/* ---- executive summary (rule based, narrative sentences, from real fields only — never invented) ---- */
function pronounSet(gender) {
  const g = (gender || "").toLowerCase().trim();
  if (g.startsWith("f")) return { subject: "she", possessive: "her" };
  if (g.startsWith("m")) return { subject: "he", possessive: "his" };
  return { subject: "they", possessive: "their" };
}
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

function formatScore(score, scheme) {
  if (isNA(score)) return null;
  const s = String(score).trim();
  if (/cgpa/i.test(scheme || "")) return s.includes("/") ? `${s} CGPA` : `${s}/10 CGPA`;
  return s.includes("%") ? s : `${s}%`;
}
function fmtLPA(v) {
  if (isNA(v)) return null;
  const n = Number(v);
  if (isNaN(n)) return null;
  const lakhs = Math.round((n / 100000) * 10) / 10;
  const display = Number.isInteger(lakhs) ? lakhs.toFixed(0) : lakhs.toFixed(1);
  return `₹${display} LPA`;
}
function fmtYearsOnly(months) {
  if (isNA(months)) return null;
  const n = Number(months);
  if (isNaN(n) || n <= 0) return null;
  const y = Math.max(1, Math.round(n / 12));
  return `${y} year${y === 1 ? "" : "s"}`;
}

function computeAge(dobStr) {
  if (isNA(dobStr)) return null;
  const m = String(dobStr).trim().match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})$/);
  if (!m) return null;
  let [, d, mo, y] = m;
  d = Number(d); mo = Number(mo); y = Number(y);
  if (y < 100) y += y <= 30 ? 2000 : 1900; // 2-digit year heuristic
  const dob = new Date(y, mo - 1, d);
  if (isNaN(dob.getTime())) return null;
  const now = new Date();
  let age = now.getFullYear() - dob.getFullYear();
  const monthDiff = now.getMonth() - dob.getMonth();
  if (monthDiff < 0 || (monthDiff === 0 && now.getDate() < dob.getDate())) age--;
  return age > 0 && age < 100 ? age : null;
}

function initialsOf(name) {
  if (!name) return "?";
  const parts = name.trim().split(/\s+/);
  return ((parts[0]?.[0] || "") + (parts[1]?.[0] || "")).toUpperCase() || parts[0]?.[0]?.toUpperCase() || "?";
}
const AVATAR_GRADIENTS = [
  ["#39B6D8", "#177E9C"], ["#F7D344", "#E38330"], ["#8B7CF6", "#5B4FCF"],
  ["#E38330", "#C0392B"], ["#1E8E3E", "#177E9C"], ["#E88BAF", "#C0567F"],
];
function avatarGradient(seed) {
  let h = 0;
  for (let i = 0; i < (seed || "").length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return AVATAR_GRADIENTS[h % AVATAR_GRADIENTS.length];
}
function fmtExpShort(months) {
  if (isNA(months)) return null;
  const n = Number(months);
  if (isNaN(n) || n <= 0) return null;
  const y = Math.floor(n / 12);
  const m = Math.round(n % 12);
  if (y === 0) return `${m}m`;
  if (m === 0) return `${y}y`;
  return `${y}y ${m}m`;
}

function buildSummary(c, opts = {}) {
  const { includeInterview = false } = opts;
  const p = pronounSet(c.gender);
  const firstName = (c.name || "This candidate").split(" ")[0];
  const sentences = [];

  /* Sentence 1 — academics */
  const c10 = formatScore(c.class10.score, c.class10.scheme);
  const c12 = formatScore(c.class12.score, c.class12.scheme);
  const gradScore = formatScore(c.grad.score, c.grad.scheme);
  const gradInst = c.grad.institute || c.grad.university;
  const board = c.class12.board || c.class10.board;

  if (c10 || c12) {
    const parts = [];
    if (c10) parts.push(`${c10} in Class 10`);
    if (c12) parts.push(`${c12} in Class 12${board ? ` (${board})` : ""}`);
    let s = `${firstName} scored ${parts.join(" and ")}`;
    s += gradScore
      ? `, followed by a ${gradScore} in ${c.grad.degree || "his/her undergraduate"} degree${gradInst ? ` from ${gradInst}` : ""}.`
      : ".";
    sentences.push(s);
  } else if (gradScore) {
    sentences.push(`${firstName} completed a ${gradScore} in ${c.grad.degree || "an undergraduate"} degree${gradInst ? ` from ${gradInst}` : ""}.`);
  }

  /* Sentence 2 — experience */
  const totalYears = fmtYearsOnly(c.totalExpMonths);
  const currentYears = fmtYearsOnly(c.currentExpMonths);
  const currentCompany = c.corporateExp[0]?.org || c.familyBizExp[0]?.org || c.startupExp[0]?.org;
  const ctc = fmtLPA(c.grossCTC);
  if (totalYears) {
    let s = `${cap(p.subject)} has ${totalYears} of experience`;
    if (currentYears && currentCompany) s += `, including ${currentYears} at ${currentCompany}`;
    else if (currentCompany) s += `, currently at ${currentCompany}`;
    if (ctc) s += `, where ${p.subject} currently earns ${ctc}`;
    sentences.push(s + ".");
  } else if (currentCompany) {
    sentences.push(`${cap(p.subject)} currently works at ${currentCompany}${c.currentDesignation ? ` as ${c.currentDesignation}` : ""}${ctc ? `, earning ${ctc}` : ""}.`);
  }

  /* Sentence 3 — differentiators (only when the underlying data actually exists) */
  const diffs = [];
  if (c.diploma?.name) diffs.push(`a ${c.diploma.name} by profession`);
  if (c.familyBizName) diffs.push(`associated with the family business ${c.familyBizName}`);
  if (diffs.length) sentences.push(`${cap(p.subject === "they" ? "They are" : p.subject + " is")} ${diffs.join(", and ")}.`);
  if (!isNA(c.entrepreneurshipInterest)) sentences.push(`${cap(p.subject)} rate${p.subject === "they" ? "" : "s"} ${p.possessive} interest in entrepreneurship at ${c.entrepreneurshipInterest}/10.`);

  /* Sentence 4 — interview outcome (only visible/available at Pratham's post-interview stage) */
  if (includeInterview && c.interview.interviewerName && c.interview.finalRecommendation) {
    sentences.push(`Interviewed by ${c.interview.interviewerName}, ${p.subject} was rated ${c.interview.finalRecommendation}.`);
  }

  return sentences.slice(0, 5);
}

/* ============================== STORAGE HOOK ============================== */
function useStorage(key, shared, initial) {
  const [value, setValue] = useState(initial);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await window.storage.get(key, shared);
        if (!cancelled && res && res.value !== undefined) {
          try { setValue(JSON.parse(res.value)); } catch { setValue(res.value); }
        }
      } catch (e) {
        /* key not found - keep initial */
      } finally {
        if (!cancelled) setLoaded(true);
      }
    })();
    return () => { cancelled = true; };
  }, [key, shared]);

  const update = useCallback(async (updater) => {
    setValue((prev) => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      window.storage.set(key, JSON.stringify(next), shared).catch((e) => console.error("storage set failed", e));
      return next;
    });
  }, [key, shared]);

  return [value, update, loaded];
}

/* ============================== APP ============================== */
/* ============================== ROOT APP (auth gate) ============================== */
export default function App() {
  const [identity, setIdentity, identityLoaded] = useStorage("current-identity", false, null);

  if (!identityLoaded) return <div style={{ minHeight: "100vh", background: "#0B0B0C" }} />;
  if (!identity) return <AccessScreen onAuthenticated={(u) => setIdentity(u)} />;
  return <Workspace identity={identity} onSignOut={() => setIdentity(null)} />;
}

/* ============================== WORKSPACE (authenticated app) ============================== */
function Workspace({ identity, onSignOut }) {
  const role = identity.role;
  const rawCandidates = useMemo(() => decodeCandidates(CANDIDATES_B64), []);
  const initialCandidates = useMemo(() => rawCandidates.map(normalize), [rawCandidates]);

  const [candidates, setCandidates] = useState(initialCandidates);
  const [evalMap, setEvalMap, evalLoaded] = useStorage("evaluations", true, {});
  const [historyMap, setHistoryMap] = useStorage("history", true, {});
  const [roundConfig, setRoundConfig] = useStorage("round-config", true, DEFAULT_ROUND);
  const [tourSeenMap, setTourSeenMap, tourSeenLoaded] = useStorage("tour-seen", false, {});
  const [tourActive, setTourActive] = useState(false);

  useEffect(() => {
    if (!tourSeenLoaded) return;
    if (!tourSeenMap || !tourSeenMap[role]) {
      const t = setTimeout(() => setTourActive(true), 600);
      return () => clearTimeout(t);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [role, tourSeenLoaded]);

  const finishTour = () => {
    setTourActive(false);
    setTourSeenMap((prev) => ({ ...(prev || {}), [role]: true }));
  };
  const startTour = () => setTourActive(true);

  // seed evalMap from CSV existing evaluator columns once, without clobbering stored decisions
  useEffect(() => {
    if (!evalLoaded) return;
    setEvalMap((prev) => {
      const next = { ...prev };
      let changed = false;
      candidates.forEach((c) => {
        if (!next[c.appNo]) {
          const seed = {};
          if (c.evaluators.shivas.category) seed.shivas = { category: c.evaluators.shivas.category, comments: c.evaluators.shivas.comments, ts: null, seeded: true };
          if (c.evaluators.pratham.category) seed.pratham = { category: c.evaluators.pratham.category, comments: c.evaluators.pratham.comments, scholarship: c.evaluators.pratham.scholarship, ts: null, seeded: true };
          if (Object.keys(seed).length) { next[c.appNo] = seed; changed = true; }
        }
      });
      return changed ? next : prev;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [evalLoaded]);

  const [adminEvaluatorId, setAdminEvaluatorId] = useState("shivas"); // only used when role === admin
  const activeEvaluatorId = role === "admin" ? adminEvaluatorId : role;
  const activeEvaluator = EVALUATORS[activeEvaluatorId];

  const [view, setView] = useState(role === "admin" ? "dashboard" : "queue"); // dashboard | queue | all | profile | quick | analysis | downloads | settings
  const [queueSource, setQueueSource] = useState("queue"); // which list feeds Next/Prev in profile: queue | completed | skipped | all
  const [queueSubTab, setQueueSubTab] = useState("pending"); // pending | completed | skipped
  const [selectedAppNo, setSelectedAppNo] = useState(null);
  const [search, setSearch] = useState("");
  const [filters, setFilters] = useState({ course: "", gender: "", stage: "", shivasCat: "", prathamCat: "", scholarship: "" });
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [modalState, setModalState] = useState(null); // {appNo, evaluatorId, preselect}
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [syncOpen, setSyncOpen] = useState(false);
  const [skippedMap, setSkippedMap] = useStorage("skipped", true, {}); // { evaluatorId: { appNo: ts } }

  const isSkipped = useCallback((evaluatorId, appNo) => !!(skippedMap[evaluatorId] && skippedMap[evaluatorId][appNo]), [skippedMap]);
  const toggleSkip = useCallback((evaluatorId, appNo) => {
    setSkippedMap((prev) => {
      const next = { ...prev };
      const forEval = { ...(next[evaluatorId] || {}) };
      if (forEval[appNo]) delete forEval[appNo];
      else forEval[appNo] = new Date().toISOString();
      next[evaluatorId] = forEval;
      return next;
    });
  }, [setSkippedMap]);

  /* --------- derived: evaluation-aware candidate list --------- */
  const enriched = useMemo(() => {
    return candidates.map((c) => {
      const ev = evalMap[c.appNo] || {};
      const shivasDone = !!(ev.shivas && ev.shivas.category);
      const shivasRejected = shivasDone && ev.shivas.category === "Rejected";
      const prathamDone = !!(ev.pratham && ev.pratham.category);
      let stage = "New";
      if (shivasDone && shivasRejected) stage = "Rejected by Evaluator 1";
      else if (shivasDone && !prathamDone) stage = "Advanced — Pending Evaluator 2";
      else if (shivasDone && prathamDone) stage = "Evaluator 2 Evaluated";
      else stage = "Evaluator 1 Pending";
      return { ...c, ev, shivasDone, shivasRejected, prathamDone, stage, complete: completeness(c) };
    });
  }, [candidates, evalMap]);

  const byAppNo = useMemo(() => {
    const m = {};
    enriched.forEach((c) => (m[c.appNo] = c));
    return m;
  }, [enriched]);

  /* --------- search + filters --------- */
  const searchFiltered = useMemo(() => {
    let list = enriched;
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      list = list.filter((c) =>
        [c.name, c.appNo, c.email, c.phone, c.linkedin, c.course, c.corporateExp[0]?.org, c.grad.institute]
          .some((f) => f && String(f).toLowerCase().includes(q))
      );
    }
    if (filters.course) list = list.filter((c) => c.course === filters.course);
    if (filters.gender) list = list.filter((c) => c.gender === filters.gender);
    if (filters.stage) list = list.filter((c) => c.stage === filters.stage);
    if (filters.shivasCat) list = list.filter((c) => c.ev.shivas?.category === filters.shivasCat);
    if (filters.prathamCat) list = list.filter((c) => c.ev.pratham?.category === filters.prathamCat);
    if (filters.scholarship) list = list.filter((c) => c.ev.pratham?.scholarship === filters.scholarship);
    return list;
  }, [enriched, search, filters]);

  /* --------- evaluator queues (enforced) --------- */
  const shivasQueue = useMemo(() => searchFiltered.filter((c) => !c.shivasDone), [searchFiltered]);
  const prathamQueue = useMemo(() => searchFiltered.filter((c) => c.shivasDone && !c.shivasRejected && !c.prathamDone), [searchFiltered]);
  const activeQueue = activeEvaluatorId === "shivas" ? shivasQueue : prathamQueue;

  const pendingList = useMemo(() => activeQueue.filter((c) => !isSkipped(activeEvaluatorId, c.appNo)), [activeQueue, isSkipped, activeEvaluatorId]);
  const skippedList = useMemo(() => activeQueue.filter((c) => isSkipped(activeEvaluatorId, c.appNo)), [activeQueue, isSkipped, activeEvaluatorId]);
  const completedList = useMemo(() => searchFiltered.filter((c) => c.ev[activeEvaluatorId] && c.ev[activeEvaluatorId].category), [searchFiltered, activeEvaluatorId]);

  const pendingShivasCount = useMemo(() => shivasQueue.filter((c) => !isSkipped("shivas", c.appNo)).length, [shivasQueue, isSkipped]);
  const pendingPrathamCount = useMemo(() => prathamQueue.filter((c) => !isSkipped("pratham", c.appNo)).length, [prathamQueue, isSkipped]);

  const activeList = useMemo(() => {
    if (queueSource === "queue") return pendingList;
    if (queueSource === "completed") return completedList;
    if (queueSource === "skipped") return skippedList;
    return searchFiltered;
  }, [queueSource, pendingList, completedList, skippedList, searchFiltered]);

  const selectedIndex = activeList.findIndex((c) => c.appNo === selectedAppNo);
  const selected = selectedAppNo ? byAppNo[selectedAppNo] : null;

  const openProfile = (appNo, source = "queue") => {
    setQueueSource(source);
    if (source === "queue") setQueueSubTab("pending");
    else if (source === "completed") setQueueSubTab("completed");
    else if (source === "skipped") setQueueSubTab("skipped");
    setSelectedAppNo(appNo);
    setView("profile");
  };
  const goNext = () => {
    if (selectedIndex >= 0 && selectedIndex < activeList.length - 1) setSelectedAppNo(activeList[selectedIndex + 1].appNo);
  };
  const goPrev = () => {
    if (selectedIndex > 0) setSelectedAppNo(activeList[selectedIndex - 1].appNo);
  };

  /* --------- save evaluation --------- */
  const saveEvaluation = async (appNo, evaluatorId, category, comments, scholarship) => {
    const ts = new Date().toISOString();
    setEvalMap((prev) => {
      const next = { ...prev };
      const prevForCandidate = next[appNo] || {};
      const prevEntry = prevForCandidate[evaluatorId];
      next[appNo] = {
        ...prevForCandidate,
        [evaluatorId]: { category, comments, scholarship: scholarship || null, ts, evaluator: EVALUATORS[evaluatorId].name },
      };
      // history log
      setHistoryMap((h) => {
        const hn = { ...h };
        const list = hn[appNo] ? [...hn[appNo]] : [];
        list.push({
          evaluator: EVALUATORS[evaluatorId].name, stage: EVALUATORS[evaluatorId].stage, ts,
          category, comments, scholarship: scholarship || null,
          previous: prevEntry ? prevEntry.category : null,
        });
        hn[appNo] = list;
        return hn;
      });
      return next;
    });
    // evaluating a candidate clears any "skipped" flag for that evaluator — they're no longer parked
    if (isSkipped(evaluatorId, appNo)) toggleSkip(evaluatorId, appNo);
  };

  /* --------- admin-only: reset an evaluation --------- */
  const resetEvaluation = async (appNo, evaluatorId) => {
    const ts = new Date().toISOString();
    setEvalMap((prev) => {
      const next = { ...prev };
      const prevForCandidate = next[appNo] || {};
      const prevEntry = prevForCandidate[evaluatorId];
      if (!prevEntry) return prev;
      const rest = { ...prevForCandidate };
      delete rest[evaluatorId];
      next[appNo] = rest;
      setHistoryMap((h) => {
        const hn = { ...h };
        const list = hn[appNo] ? [...hn[appNo]] : [];
        list.push({
          evaluator: `${identity.full} (Admin reset)`, stage: EVALUATORS[evaluatorId].stage, ts,
          category: null, comments: `Reset of ${EVALUATORS[evaluatorId].name}'s evaluation.`, scholarship: null,
          previous: prevEntry.category, action: "reset",
        });
        hn[appNo] = list;
        return hn;
      });
      return next;
    });
  };

  /* --------- import / sync --------- */
  const handleImportRows = (rows) => {
    const normalized = rows.map(normalize);
    setCandidates((prev) => {
      const map = {};
      prev.forEach((c) => (map[c.appNo] = c));
      normalized.forEach((c) => (map[c.appNo] = c)); // overwrite app data only; evaluations live separately in evalMap
      return Object.values(map);
    });
  };

  const totalCandidates = candidates.length;
  const navItems = ROLE_NAV[role] || ROLE_NAV.shivas;

  return (
    <div className="mu-root">
      <GlobalStyle />
      <TopBar
        identity={identity} onSignOut={onSignOut}
        sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen}
        onSync={() => setSyncOpen(true)} onStartTour={startTour}
        showSync={role === "admin"}
      />
      <div style={{ display: "flex" }}>
        <SideNav view={view} setView={(v) => { setView(v); setSidebarOpen(false); }} sidebarOpen={sidebarOpen}
          shivasQueueCount={pendingShivasCount} prathamQueueCount={pendingPrathamCount} activeEvaluatorId={activeEvaluatorId}
          navItems={navItems} />
        {sidebarOpen && <div className="mu-hide-desktop" onClick={() => setSidebarOpen(false)} style={{ position: "fixed", inset: "57px 0 0 0", background: "rgba(0,0,0,0.35)", zIndex: 80 }} />}
        <main className="mu-main" style={{ flex: 1, minWidth: 0, padding: "77px 22px 90px" }}>
          {(view === "queue" || view === "profile" || view === "quick") && role === "admin" && (
            <EvaluatorTabs activeEvaluatorId={adminEvaluatorId} setActiveEvaluatorId={(id) => { setAdminEvaluatorId(id); setSelectedAppNo(null); }} locked={false} />
          )}
          {view === "dashboard" && (
            <Dashboard candidates={enriched} evalMap={evalMap} roundConfig={roundConfig}
              onOpenQueue={() => setView("queue")} onOpenProfile={(a) => openProfile(a, "all")} />
          )}
          {view === "queue" && (
            <EvaluatorQueueView
              evaluator={activeEvaluator}
              pendingList={pendingList} completedList={completedList} skippedList={skippedList}
              subTab={queueSubTab} setSubTab={setQueueSubTab}
              search={search} setSearch={setSearch}
              filters={filters} setFilters={setFilters} filtersOpen={filtersOpen} setFiltersOpen={setFiltersOpen}
              candidatesAll={enriched}
              onOpen={(a, sub) => openProfile(a, sub === "pending" ? "queue" : sub)}
              onToggleSkip={(appNo) => toggleSkip(activeEvaluatorId, appNo)}
            />
          )}
          {view === "all" && (
            <CandidateList
              title="All Candidates" subtitle={`${searchFiltered.length} of ${totalCandidates} candidates`}
              list={searchFiltered} search={search} setSearch={setSearch}
              filters={filters} setFilters={setFilters} filtersOpen={filtersOpen} setFiltersOpen={setFiltersOpen}
              candidatesAll={enriched}
              onOpen={(a) => openProfile(a, "all")}
              emptyMsg="No candidates match these filters."
            />
          )}
          {view === "profile" && selected && (
            <CandidateProfile
              candidate={selected} evaluator={activeEvaluator}
              onNext={goNext} onPrev={goPrev}
              hasNext={selectedIndex < activeList.length - 1} hasPrev={selectedIndex > 0}
              index={selectedIndex} total={activeList.length}
              onEvaluate={(preselect) => setModalState({ appNo: selected.appNo, evaluatorId: activeEvaluator.id, preselect })}
              history={historyMap[selected.appNo] || []}
              onBack={() => setView(queueSource === "all" ? "all" : "queue")}
              role={role}
              onReset={(evaluatorId) => resetEvaluation(selected.appNo, evaluatorId)}
              isSkipped={isSkipped(activeEvaluator.id, selected.appNo)}
              onToggleSkip={() => toggleSkip(activeEvaluator.id, selected.appNo)}
            />
          )}
          {view === "profile" && !selected && (
            <EmptyState title="No candidate selected" body="Go to a queue or All Candidates to open a profile." />
          )}
          {view === "quick" && (
            <QuickEvaluate list={pendingList} evaluator={activeEvaluator}
              onEvaluate={(appNo, evaluatorId, preselect) => setModalState({ appNo, evaluatorId, preselect })}
              onSkip={(appNo) => toggleSkip(activeEvaluator.id, appNo)}
            />
          )}
          {view === "analysis" && (
            <Analysis candidates={enriched} evalMap={evalMap} />
          )}
          {view === "downloads" && (
            <Downloads candidates={enriched} filtered={searchFiltered} />
          )}
          {view === "settings" && (
            <RoundSettings roundConfig={roundConfig} setRoundConfig={setRoundConfig} candidates={enriched} />
          )}
        </main>
      </div>

      {modalState && (
        <EvaluationModal
          candidate={byAppNo[modalState.appNo]}
          evaluator={EVALUATORS[modalState.evaluatorId]}
          preselect={modalState.preselect}
          onClose={() => setModalState(null)}
          onSave={async (category, comments, scholarship) => {
            await saveEvaluation(modalState.appNo, modalState.evaluatorId, category, comments, scholarship);
            setModalState(null);
          }}
        />
      )}
      {syncOpen && <SyncModal onClose={() => setSyncOpen(false)} onImport={handleImportRows} />}
      {tourActive && <TourOverlay role={role} isModalOpen={!!modalState} onFinish={finishTour} />}
    </div>
  );
}

/* ============================== TOP BAR ============================== */
function TopBar({ identity, onSignOut, sidebarOpen, setSidebarOpen, onSync, onStartTour, showSync }) {
  const [menuOpen, setMenuOpen] = useState(false);
  return (
    <header className="mu-topbar" style={{
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "12px 20px", borderBottom: "1px solid #E5E5E5", background: "#fff",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        <button className="mu-btn mu-btn-ghost mu-hide-desktop" onClick={() => setSidebarOpen(!sidebarOpen)} style={{ padding: 6 }}>
          <Menu size={20} />
        </button>
        <MULogo height={24} />
        <span style={{ height: 22, width: 1, background: "#E5E5E5", margin: "0 4px" }} className="mu-hide-mobile" />
        <span style={{ fontSize: 12.5, color: "#A3A3A3", fontWeight: 600 }} className="mu-hide-mobile">C8 Profile Evaluation</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <button className="mu-btn mu-btn-ghost mu-hide-mobile" onClick={onStartTour} title="Show me how this works">
          <Sparkles size={14} /> Show me how this works
        </button>
        {showSync && (
          <button className="mu-btn mu-btn-secondary mu-hide-mobile" onClick={onSync}>
            <RefreshCw size={14} /> Sync Data
          </button>
        )}
        <div style={{ position: "relative" }}>
          <button className="mu-btn mu-btn-secondary" onClick={() => setMenuOpen(!menuOpen)} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ width: 22, height: 22, borderRadius: 999, background: "#171717", color: "#fff", fontSize: 11, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>
              {identity.full.split(" ").map((p) => p[0]).slice(0, 2).join("")}
            </span>
            <span className="mu-hide-mobile" style={{ textAlign: "left" }}>
              <span style={{ display: "block", fontSize: 12.5, fontWeight: 700, lineHeight: 1.1 }}>{identity.full}</span>
              <span style={{ display: "block", fontSize: 10.5, color: "#A3A3A3", lineHeight: 1.1 }}>{ROLE_LABELS[identity.role]}</span>
            </span>
            <ChevronDown size={13} />
          </button>
          {menuOpen && (
            <div style={{ position: "absolute", right: 0, top: "calc(100% + 6px)", background: "#fff", border: "1px solid #E5E5E5", borderRadius: 10, boxShadow: "0 10px 30px rgba(0,0,0,0.12)", minWidth: 170, zIndex: 60, overflow: "hidden" }}>
              <button className="mu-btn mu-btn-ghost mu-hide-desktop" style={{ width: "100%", justifyContent: "flex-start", borderRadius: 0, padding: "10px 14px" }} onClick={() => { setMenuOpen(false); onStartTour(); }}>Show me how this works</button>
              <button className="mu-btn mu-btn-ghost" style={{ width: "100%", justifyContent: "flex-start", borderRadius: 0, padding: "10px 14px", color: "#C0392B" }} onClick={onSignOut}>Not you? Switch user</button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

/* ============================== EVALUATOR TABS ============================== */
function EvaluatorTabs({ activeEvaluatorId, setActiveEvaluatorId, locked }) {
  const evaluatorsToShow = locked ? [EVALUATORS[activeEvaluatorId]] : Object.values(EVALUATORS);
  return (
    <div data-tour="evaluator-tabs" style={{ display: "flex", gap: 8, marginBottom: 16 }}>
      {evaluatorsToShow.map((e) => {
        const active = e.id === activeEvaluatorId;
        return (
          <button
            key={e.id}
            disabled={locked}
            onClick={() => !locked && setActiveEvaluatorId(e.id)}
            className="mu-btn"
            style={{
              padding: "9px 18px", borderRadius: 10,
              background: active ? "#171717" : "#fff",
              color: active ? "#fff" : "#404040",
              border: `1px solid ${active ? "#171717" : "#E5E5E5"}`,
              cursor: locked ? "default" : "pointer",
            }}
          >
            {e.name} <span style={{ fontSize: 11, opacity: 0.7 }}>· Stage {e.stage}</span>
          </button>
        );
      })}
    </div>
  );
}

/* ============================== SIDE NAV ============================== */
function NavItem({ icon: Icon, label, active, onClick, badge, tourId }) {
  return (
    <button data-tour={tourId} onClick={onClick} style={{
      display: "flex", alignItems: "center", gap: 10, width: "100%", textAlign: "left",
      padding: "9px 12px", borderRadius: 10, border: "none",
      background: active ? "#171717" : "transparent", color: active ? "#fff" : "#404040",
      fontSize: 13.5, fontWeight: 600, marginBottom: 3,
    }}>
      <Icon size={16} />
      <span style={{ flex: 1 }}>{label}</span>
      {badge > 0 && (
        <span style={{
          background: active ? "#39B6D8" : "#F7D344", color: active ? "#fff" : "#171717",
          fontSize: 10.5, fontWeight: 700, borderRadius: 999, padding: "1px 7px", minWidth: 18, textAlign: "center",
        }}>{badge}</span>
      )}
    </button>
  );
}

function SideNav({ view, setView, sidebarOpen, shivasQueueCount, prathamQueueCount, activeEvaluatorId, navItems }) {
  const queueCount = activeEvaluatorId === "shivas" ? shivasQueueCount : prathamQueueCount;
  const allItems = [
    { id: "dashboard", label: "Dashboard", icon: LayoutDashboard, tourId: "nav-dashboard" },
    { id: "queue", label: "Evaluator Queue", icon: ClipboardList, badge: queueCount, tourId: "nav-queue" },
    { id: "all", label: "All Candidates", icon: Users, tourId: "nav-all" },
    { id: "quick", label: "Quick Evaluate", icon: Sparkles, tourId: "nav-quick" },
    { id: "analysis", label: "Analysis", icon: BarChart3, tourId: "nav-analysis" },
    { id: "downloads", label: "Downloads", icon: Download, tourId: "nav-downloads" },
    { id: "settings", label: "Round Management", icon: Settings, tourId: "nav-settings" },
  ];
  const items = allItems.filter((it) => navItems.includes(it.id));
  return (
    <nav
      className={`mu-sidenav ${sidebarOpen ? "mu-sidenav-open" : "mu-hide-mobile"}`}
      style={{
        width: 218, flexShrink: 0, borderRight: "1px solid #E5E5E5", background: "#fff",
        padding: "16px 12px",
      }}
    >
      {items.map((it) => (
        <NavItem key={it.id} icon={it.icon} label={it.label} active={view === it.id} badge={it.badge} tourId={it.tourId} onClick={() => setView(it.id)} />
      ))}
    </nav>
  );
}

/* ============================== SHARED BITS ============================== */
function EmptyState({ title, body, icon: Icon = FileQuestion }) {
  return (
    <div style={{ textAlign: "center", padding: "70px 20px", color: "#A3A3A3" }}>
      <Icon size={34} style={{ marginBottom: 10, opacity: 0.5 }} />
      <div style={{ fontWeight: 700, fontSize: 15, color: "#525252" }}>{title}</div>
      <div style={{ fontSize: 13, marginTop: 4 }}>{body}</div>
    </div>
  );
}

function CategoryBadge({ category }) {
  if (!category) return <span className="mu-badge" style={{ background: "#F5F5F5", color: "#A3A3A3" }}>Pending</span>;
  let bg = "#E8F7FB", fg = "#177E9C";
  if (/reject/i.test(category)) { bg = "#FDECEC"; fg = "#C0392B"; }
  else if (/unable/i.test(category)) { bg = "#F5F5F5"; fg = "#737373"; }
  else if (/waitlist/i.test(category)) { bg = "#FEF6E4"; fg = "#B7791F"; }
  else if (/^A1/.test(category)) { bg = "#EAF7EC"; fg = "#1E8E3E"; }
  return <span className="mu-badge" style={{ background: bg, color: fg }}>{category}</span>;
}

function ActionIcons({ candidate, size = 15 }) {
  const items = [
    { icon: Linkedin, url: candidate.linkedin, label: "LinkedIn" },
    { icon: Instagram, url: candidate.instaOrWebsite, label: "Instagram/Website" },
    { icon: FileText, url: candidate.cv, label: "CV" },
    { icon: Award, url: candidate.mubaatReport, label: "MUBAAT" },
    { icon: Video, url: candidate.interview.interviewLink, label: "Interview" },
    { icon: PlayCircle, url: candidate.interview.recording, label: "Recording" },
  ];
  return (
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
      {items.map((it, i) => (
        <button key={i} disabled={!it.url} title={it.label}
          onClick={(e) => { e.stopPropagation(); openLink(it.url); }}
          className="mu-btn mu-btn-secondary" style={{ padding: "6px 9px" }}>
          <it.icon size={size} />
        </button>
      ))}
    </div>
  );
}

/* ============================== DASHBOARD ============================== */
function Dashboard({ candidates, roundConfig, onOpenQueue, onOpenProfile }) {
  const total = candidates.length;
  const shivasReviewed = candidates.filter((c) => c.shivasDone).length;
  const shivasRejected = candidates.filter((c) => c.shivasRejected).length;
  const prathamPool = candidates.filter((c) => c.shivasDone && !c.shivasRejected).length;
  const prathamReviewed = candidates.filter((c) => c.prathamDone).length;
  const selected = candidates.filter((c) => c.ev.pratham && /^A/.test(c.ev.pratham.category)).length;
  const waitlisted = candidates.filter((c) => c.ev.pratham?.category === "Waitlisted").length;
  const finalRejected = candidates.filter((c) => c.ev.pratham?.category === "Rejected").length;
  const interviewedNotEvaluated = candidates.filter((c) => c.interview.status && c.shivasDone && !c.shivasRejected && !c.prathamDone).length;
  const missingRecording = candidates.filter((c) => c.interview.interviewLink && !c.interview.recording).length;

  const stat = (label, value, color = "#171717") => (
    <div className="mu-card mu-stat" style={{ padding: "16px 18px", flex: "1 1 140px" }}>
      <div style={{ fontSize: 11.5, color: "#A3A3A3", fontWeight: 600, textTransform: "uppercase", letterSpacing: ".04em" }}>{label}</div>
      <div className="mu-stat-value" style={{ fontSize: 26, fontWeight: 800, color, marginTop: 4 }}>{value}</div>
    </div>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 18, flexWrap: "wrap", gap: 10 }}>
        <div>
          <h1 className="mu-page-title" style={{ fontSize: 22, fontWeight: 800, margin: 0 }}>Admissions Overview</h1>
          <div style={{ color: "#737373", fontSize: 13.5, marginTop: 3 }}>{roundConfig.name} · Deadline extended to {new Date(roundConfig.extendedDeadline).toLocaleString()}</div>
        </div>
        <button className="mu-btn mu-btn-primary" onClick={onOpenQueue}>Go to Evaluator Queue <ChevronRight size={15} /></button>
      </div>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 18 }}>
        {stat("Applications", total)}
        {stat("Shivas Reviewed", `${shivasReviewed}/${total}`, BRAND.blue)}
        {stat("Advanced to Pratham", prathamPool)}
        {stat("Pratham Reviewed", `${prathamReviewed}/${prathamPool}`, BRAND.orange)}
        {stat("Selected", selected, "#1E8E3E")}
        {stat("Waitlisted", waitlisted, "#B7791F")}
        {stat("Rejected (either stage)", shivasRejected + finalRejected, "#C0392B")}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.3fr 1fr", gap: 14 }} className="mu-fieldgrid-cols">
        <div className="mu-card" style={{ padding: 18 }}>
          <div className="mu-section-title">Funnel</div>
          <FunnelBars total={total} shivasReviewed={shivasReviewed} shivasAdvanced={prathamPool} prathamReviewed={prathamReviewed} selected={selected} />
        </div>
        <div className="mu-card" style={{ padding: 18 }}>
          <div className="mu-section-title"><AlertTriangle size={13} /> Alerts</div>
          <AlertRow text={`${prathamPool - prathamReviewed} candidates awaiting Pratham evaluation`} show={prathamPool - prathamReviewed > 0} />
          <AlertRow text={`${interviewedNotEvaluated} candidates interviewed but not yet evaluated by Pratham`} show={interviewedNotEvaluated > 0} />
          <AlertRow text={`${missingRecording} candidates missing interview recording`} show={missingRecording > 0} />
          <AlertRow text={`Round deadline: ${new Date(roundConfig.extendedDeadline).toLocaleDateString()}`} show={true} muted />
          {(prathamPool - prathamReviewed <= 0 && interviewedNotEvaluated <= 0 && missingRecording <= 0) && (
            <div style={{ color: "#A3A3A3", fontSize: 13, marginTop: 6 }}>No urgent alerts.</div>
          )}
        </div>
      </div>

      <div className="mu-card" style={{ padding: 18, marginTop: 14 }}>
        <div className="mu-section-title">Recently Updated Candidates</div>
        <RecentTable candidates={candidates} onOpen={onOpenProfile} />
      </div>
    </div>
  );
}

function AlertRow({ text, show, muted }) {
  if (!show) return null;
  return (
    <div style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: "7px 0", borderBottom: "1px solid #F5F5F5", fontSize: 13, color: muted ? "#737373" : "#171717" }}>
      <span style={{ width: 6, height: 6, borderRadius: 999, background: muted ? "#D4D4D4" : BRAND.orange, marginTop: 6, flexShrink: 0 }} />
      {text}
    </div>
  );
}

function FunnelBars({ total, shivasReviewed, shivasAdvanced, prathamReviewed, selected }) {
  const stages = [
    { label: "Applications Received", value: total },
    { label: "Evaluated by Shivas", value: shivasReviewed },
    { label: "Advanced by Shivas", value: shivasAdvanced },
    { label: "Evaluated by Pratham", value: prathamReviewed },
    { label: "Final Selected", value: selected },
  ];
  const max = total || 1;
  return (
    <div>
      {stages.map((s, i) => (
        <div key={i} style={{ marginBottom: 10 }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 4 }}>
            <span style={{ fontWeight: 600, color: "#404040" }}>{s.label}</span>
            <span style={{ color: "#A3A3A3" }}>{s.value} · {max ? Math.round((s.value / max) * 100) : 0}%</span>
          </div>
          <div style={{ height: 9, borderRadius: 999, background: "#F0F0F0", overflow: "hidden" }}>
            <div style={{ height: "100%", width: `${(s.value / max) * 100}%`, background: `linear-gradient(90deg, ${BRAND.blue}, ${BRAND.orange})`, borderRadius: 999, transition: "width .4s ease" }} />
          </div>
        </div>
      ))}
    </div>
  );
}

function RecentTable({ candidates, onOpen }) {
  const withTs = candidates.map((c) => {
    const ts = Math.max(
      c.ev.shivas?.ts ? new Date(c.ev.shivas.ts).getTime() : 0,
      c.ev.pratham?.ts ? new Date(c.ev.pratham.ts).getTime() : 0
    );
    return { c, ts };
  }).filter((x) => x.ts > 0).sort((a, b) => b.ts - a.ts).slice(0, 6);

  if (!withTs.length) return <EmptyState title="No evaluations yet" body="Evaluated candidates will appear here." />;
  return (
    <div style={{ overflowX: "auto" }}>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13 }}>
        <thead>
          <tr style={{ textAlign: "left", color: "#A3A3A3", fontSize: 11.5, textTransform: "uppercase" }}>
            <th style={{ padding: "6px 8px" }}>Candidate</th><th>Shivas</th><th>Pratham</th><th>Updated</th>
          </tr>
        </thead>
        <tbody>
          {withTs.map(({ c, ts }) => (
            <tr key={c.appNo} onClick={() => onOpen(c.appNo)} style={{ cursor: "pointer", borderTop: "1px solid #F5F5F5" }}>
              <td style={{ padding: "9px 8px", fontWeight: 600 }}>{c.name}<div style={{ fontWeight: 400, color: "#A3A3A3", fontSize: 11.5 }}>{c.appNo}</div></td>
              <td><CategoryBadge category={c.ev.shivas?.category} /></td>
              <td><CategoryBadge category={c.ev.pratham?.category} /></td>
              <td style={{ color: "#A3A3A3" }}>{new Date(ts).toLocaleDateString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

