/* ============================== EVALUATOR QUEUE VIEW (Pending / Completed / Skipped) ============================== */
function EvaluatorQueueView({ evaluator, pendingList, completedList, skippedList, subTab, setSubTab, search, setSearch, filters, setFilters, filtersOpen, setFiltersOpen, candidatesAll, onOpen, onToggleSkip }) {
  const uniq = (fn) => [...new Set(candidatesAll.map(fn).filter(Boolean))];
  const courses = uniq((c) => c.course);
  const genders = uniq((c) => c.gender);
  const stages = uniq((c) => c.stage);
  const shivasCats = uniq((c) => c.ev.shivas?.category);
  const prathamCats = uniq((c) => c.ev.pratham?.category);
  const scholarships = uniq((c) => c.ev.pratham?.scholarship);

  const tabs = [
    { id: "pending", label: "Pending", count: pendingList.length, icon: ClipboardList },
    { id: "completed", label: "Completed", count: completedList.length, icon: CircleCheck },
    { id: "skipped", label: "Skipped", count: skippedList.length, icon: SkipForward },
  ];
  const list = subTab === "pending" ? pendingList : subTab === "completed" ? completedList : skippedList;
  const emptyMsg = subTab === "pending" ? "No candidates pending evaluation."
    : subTab === "completed" ? "You haven't evaluated any candidates yet."
    : "No candidates skipped — anything you skip will be parked here so you can return to it later.";

  return (
    <div>
      <div style={{ marginBottom: 14 }}>
        <h1 className="mu-page-title" style={{ fontSize: 22, fontWeight: 800, margin: 0 }}>{evaluator.name.split(" ")[0]}'s Queue</h1>
        <div style={{ color: "#737373", fontSize: 13.5, marginTop: 3 }}>{pendingList.length} candidates pending evaluation</div>
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
        {tabs.map((t) => {
          const active = subTab === t.id;
          return (
            <button key={t.id} onClick={() => setSubTab(t.id)} className="mu-btn" style={{
              padding: "9px 16px", borderRadius: 10,
              background: active ? "#171717" : "#fff", color: active ? "#fff" : "#404040",
              border: `1px solid ${active ? "#171717" : "#E5E5E5"}`,
            }}>
              <t.icon size={14} /> {t.label}
              <span style={{
                background: active ? "#39B6D8" : "#F0F0F0", color: active ? "#fff" : "#525252",
                fontSize: 10.5, fontWeight: 700, borderRadius: 999, padding: "1px 7px", minWidth: 18, textAlign: "center", marginLeft: 4,
              }}>{t.count}</span>
            </button>
          );
        })}
      </div>

      <div style={{ display: "flex", gap: 10, marginBottom: 12, flexWrap: "wrap" }}>
        <div style={{ position: "relative", flex: "1 1 260px" }}>
          <Search size={15} style={{ position: "absolute", left: 11, top: 11, color: "#A3A3A3" }} />
          <input className="mu-input" style={{ paddingLeft: 32 }} placeholder="Search by name, app no, email, phone, LinkedIn, college…"
            value={search} onChange={(e) => setSearch(e.target.value)} />
        </div>
        <button className="mu-btn mu-btn-secondary" onClick={() => setFiltersOpen(!filtersOpen)}>
          <Filter size={14} /> Filters {filtersOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
        </button>
      </div>

      {filtersOpen && (
        <div className="mu-card" style={{ padding: 14, marginBottom: 14, display: "flex", gap: 10, flexWrap: "wrap" }}>
          <FilterSelect label="Course" value={filters.course} options={courses} onChange={(v) => setFilters({ ...filters, course: v })} />
          <FilterSelect label="Gender" value={filters.gender} options={genders} onChange={(v) => setFilters({ ...filters, gender: v })} />
          <FilterSelect label="Stage" value={filters.stage} options={stages} onChange={(v) => setFilters({ ...filters, stage: v })} />
          <FilterSelect label="Shivas Category" value={filters.shivasCat} options={shivasCats} onChange={(v) => setFilters({ ...filters, shivasCat: v })} />
          <FilterSelect label="Pratham Category" value={filters.prathamCat} options={prathamCats} onChange={(v) => setFilters({ ...filters, prathamCat: v })} />
          <FilterSelect label="Scholarship" value={filters.scholarship} options={scholarships} onChange={(v) => setFilters({ ...filters, scholarship: v })} />
          <button className="mu-btn mu-btn-ghost" onClick={() => setFilters({ course: "", gender: "", stage: "", shivasCat: "", prathamCat: "", scholarship: "" })}>Clear all</button>
        </div>
      )}

      {list.length === 0 ? (
        <EmptyState title="Nothing here" body={emptyMsg} icon={subTab === "skipped" ? SkipForward : subTab === "completed" ? CircleCheck : Users} />
      ) : (
        <div style={{ display: "grid", gap: 10 }}>
          {list.map((c) => (
            <CandidateCard
              key={c.appNo}
              c={c}
              onOpen={() => onOpen(c.appNo, subTab)}
              extraAction={
                subTab === "pending" ? (
                  <button className="mu-btn mu-btn-secondary" onClick={(e) => { e.stopPropagation(); onToggleSkip(c.appNo); }} title="Skip for now">
                    <SkipForward size={13} /> Skip
                  </button>
                ) : subTab === "skipped" ? (
                  <button className="mu-btn mu-btn-secondary" onClick={(e) => { e.stopPropagation(); onToggleSkip(c.appNo); }} title="Move back to Pending">
                    <RefreshCw size={13} /> Move to Pending
                  </button>
                ) : null
              }
            />
          ))}
        </div>
      )}
    </div>
  );
}

